    sand:  [['saturation', '#808080', .45], ['multiply', '#e8b878', .55]],
    snow:  [['saturation', '#808080', .7], ['screen', '#c4d4e4', .5]],
    ice:   [['saturation', '#808080', .7], ['screen', '#c4d4e4', .5]],
    stone: [['saturation', '#808080', .85], ['multiply', '#b4b4b4', .3]]
