const BODEN_ZONE = { 1: [], 2: [['mitte', 1]], 3: [['sand', 1], ['ton3', .24]], 4: [['mitte', 1], ['innen', .35], ['ton4', .3]], 5: [['innen', 1]] };
const BODEN_ARTEN = ['aussen', 'mitte', 'sand', 'innen', 'ton3', 'ton4'];
