    const w = s * .82, t = y - s / 2, b = y + s / 2; g.beginPath();
    if (shape === 'round') { g.moveTo(x - w / 2, t); g.lineTo(x + w / 2, t); g.lineTo(x + w / 2, y); g.arc(x, y, w / 2, 0, Math.PI); g.closePath(); }
